import React, { useEffect, useState } from 'react';
import Swal from 'sweetalert2';
import axios from 'axios';
import { BrowserRouter as Router, Routes, Route, Link, useLocation } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';

// --- NAVBAR ---
const Navbar = ({ cartCount, isFlying }) => {
  const location = useLocation();
  const isActive = (path) => location.pathname === path;
  const user = localStorage.getItem('username');

  const handleLogout = () => {
    localStorage.clear();
    window.location.href = "/login";
  };

  return (
    <nav className="bg-white/95 backdrop-blur-md sticky top-0 z-50 w-full border-b border-gray-100 shadow-sm">
      <div className="max-w-7xl mx-auto px-6 h-20 flex justify-between items-center">
        <Link to="/" className="flex items-center space-x-3">
          <div className="bg-orange-600 p-2 rounded-full shadow-md flex items-center justify-center">
            <svg width="24" height="24" viewBox="0 0 512 512" fill="white" xmlns="http://www.w3.org/2000/svg">
              <path d="M416 0c-35.3 0-64 28.7-64 64V288c0 17.7 14.3 32 32 32h32V480c0 17.7 14.3 32 32 32s32-14.3 32-32V32C480 14.3 465.7 0 448 0H416zM80 0C44.7 0 16 28.7 16 64V224c0 35.3 28.7 64 64 64h16V480c0 17.7 14.3 32 32 32s32-14.3 32-32V288h16c35.3 0 64-28.7 64-64V64c0-35.3-28.7-64-64-64H80zM128 0V192c0 8.8-7.2 16-16 16s-16-7.2-16-16V0H80V192c0 8.8-7.2 16-16 16s-16-7.2-16-16V0H16V192c0 53 43 96 96 96v192c0 17.7 14.3 32 32 32s32-14.3 32-32V288c53 0 96-43 96-96V0H224V192c0 8.8-7.2 16-16 16s-16-7.2-16-16V0H160V192c0 8.8-7.2 16-16 16s-16-7.2-16-16V0H128z" />
            </svg>
          </div>
          <span className="font-black text-xl tracking-tighter text-gray-900 uppercase italic">Fast<span className="text-orange-600">Délice</span></span>
        </Link>

        <div className="hidden md:flex space-x-8 text-[12px] font-black uppercase text-gray-800">
          {[{ name: 'Accueil', path: '/' }, { name: 'Menu', path: '/menu' }, { name: 'À Propos', path: '/about' }, { name: 'Contact', path: '/contact' }].map((link) => (
            <Link key={link.path} to={link.path} className={`relative pb-1 transition-all duration-300 hover:text-orange-600 ${isActive(link.path) ? 'text-orange-600' : ''}`}>
              {link.name}
              {isActive(link.path) && <span className="absolute bottom-0 left-0 w-full h-0.5 bg-orange-600 rounded-full"></span>}
            </Link>
          ))}
        </div>

        <div className="flex items-center space-x-4">
          <motion.div
            animate={isFlying ? { x: [0, -10, 10, -10, 10, 0], rotate: [0, -5, 5, -5, 5, 0] } : {}}
            transition={{ duration: 0.4 }}
            id="cart-icon"
          >
            <Link to="/panier" className="relative flex items-center space-x-2 text-gray-800 hover:text-orange-600 transition pr-2">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 3h2l.4 2M7 13h10l4-8H5.4M7 13L5.4 5M7 13l-2.293 2.293c-.63.63-.184 1.707.707 1.707H17m0 0a2 2 0 100 4 2 2 0 000-4zm-8 2a2 2 0 11-4 0 2 2 0 014 0z" />
              </svg>
              <span className="bg-orange-600 text-white text-[10px] font-bold rounded-full h-5 w-5 flex items-center justify-center">{cartCount}</span>
            </Link>
          </motion.div>

          {user ? (
            <div className="flex items-center space-x-4">
              <span className="text-[16px] font-black uppercase text-black italic mx-4">{user}</span>
              <button onClick={handleLogout} className="bg-orange-600 text-white px-5 py-2.5 rounded-full text-[14px] font-black uppercase tracking-widest hover:bg-gray-900 transition shadow-lg">Quitter</button>
            </div>
          ) : (
            <>
              <Link to="/register" className="text-gray-900 hover:text-orange-600 text-[11px] font-black uppercase tracking-widest transition">S'inscrire</Link>
              <Link to="/login" className="bg-orange-600 text-white px-5 py-2.5 rounded-full text-[11px] font-black uppercase tracking-widest hover:bg-gray-900 transition shadow-lg">Connexion</Link>
            </>
          )}
        </div>
      </div>
    </nav>
  );
};

// --- LAYOUT ---
const PageLayout = ({ children, title, isHome = false }) => (
  <div className="relative min-h-screen">
    <div className={`${isHome ? 'absolute' : 'fixed'} inset-0 z-0 h-[80vh] md:h-screen`}>
      <img src="https://images.unsplash.com/photo-1513104890138-7c749659a591?q=80&w=2070" className="w-full h-full object-cover" alt="bg" />
      <div className="absolute inset-0 bg-black/50 backdrop-blur-[4px]"></div>
    </div>

    <div className="relative z-10 max-w-7xl mx-auto px-6 py-16">
      {title && (
        <div className="text-center mb-16">
          <h2 className="text-5xl md:text-7xl font-black text-white italic tracking-tighter uppercase drop-shadow-2xl">{title}</h2>
          <div className="h-1.5 w-20 bg-orange-600 mx-auto mt-4 rounded-full"></div>
        </div>
      )}
      {children}
    </div>
  </div>
);

// --- REGISTER ---
const Register = () => {
  const [formData, setFormData] = useState({ name: '', email: '', password: '' });
  const [error, setError] = useState("");

  const handleRegister = async (e) => {
    e.preventDefault();
    try {
      const res = await axios.post('http://127.0.0.1:8000/api/register/', {
        username: formData.email,
        email: formData.email,
        password: formData.password,
        first_name: formData.name
      });
      localStorage.setItem('username', res.data.username || formData.name);
      localStorage.setItem('token', res.data.token);
      window.location.href = "/";
    } catch (err) {
      setError(err.response?.data?.error || "Erreur d'inscription");
    }
  };

  return (
    <PageLayout title="Inscription">
      <div className="max-w-md mx-auto bg-white/10 backdrop-blur-2xl p-12 rounded-[3.5rem] border border-white/20">
        {error && <p className="mb-4 text-red-400 text-center font-bold">{error}</p>}
        <form className="space-y-6" onSubmit={handleRegister}>
          <input type="text" placeholder="VOTRE NOM " required className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white font-bold" 
            onChange={(e) => setFormData({...formData, name: e.target.value})} />
          <input type="email" placeholder="VOTRE E-MAIL" required className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white font-bold" 
            onChange={(e) => setFormData({...formData, email: e.target.value})} />
          <input type="password" placeholder="MOT DE PASSE" required className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white font-bold" 
            onChange={(e) => setFormData({...formData, password: e.target.value})} />
          <button type="submit" className="w-full bg-orange-600 text-white py-5 rounded-2xl font-black uppercase tracking-widest hover:bg-white hover:text-black transition">S'inscrire</button>
        </form>
      </div>
    </PageLayout>
  );
};

// --- LOGIN ---
const Login = () => {
  const [formData, setFormData] = useState({ username: '', password: '' });
  const [error, setError] = useState("");

  const handleLogin = async (e) => {
    e.preventDefault();
    try {
      const res = await axios.post('http://127.0.0.1:8000/api/login/', formData);
      localStorage.setItem('username', res.data.username || formData.username);
      localStorage.setItem('token', res.data.token);
      window.location.href = "/";
    } catch (err) {
      setError("❌ Identifiants incorrects.");
    }
  };

  return (
    <PageLayout title="Connexion">
      <div className="max-w-md mx-auto bg-white/10 backdrop-blur-2xl border border-white/20 p-12 rounded-[3.5rem]">
        {error && <p className="mb-4 text-red-400 text-center font-bold">{error}</p>}
        <form className="space-y-6" onSubmit={handleLogin}>
          <input type="text" placeholder="NOM D'UTILISATEUR" required className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white outline-none focus:border-orange-600 transition font-bold uppercase" onChange={(e) => setFormData({...formData, username: e.target.value})} />
          <input type="password" placeholder="MOT DE PASSE" required className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white outline-none focus:border-orange-600 transition font-bold" onChange={(e) => setFormData({...formData, password: e.target.value})} />
          <button type="submit" className="w-full bg-orange-600 text-white py-5 rounded-2xl font-black uppercase tracking-widest hover:bg-white hover:text-black transition shadow-lg">Se Connecter</button>
        </form>
      </div>
    </PageLayout>
  );
};

// --- ABOUT (TEXTE COMPLET RÉTABLI) ---
const About = () => (
  <PageLayout title="Notre Passion">
    <div className="max-w-5xl mx-auto space-y-12">
      <div className="bg-white/10 backdrop-blur-xl border border-white/20 p-12 rounded-[3.5rem] shadow-2xl">
        <h3 className="text-3xl font-black text-orange-600 italic mb-8 uppercase tracking-tighter text-center">Une Expérience Unique</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
          <p className="text-white text-lg leading-relaxed font-medium italic opacity-90">
            Depuis notre lancement en 2026, **FastDélice** s'est donné pour mission de redéfinir la gastronomie rapide au Maroc. Nous croyons fermement que manger vite ne devrait jamais signifier manger mal. C'est pourquoi chaque plat qui sort de notre cuisine est traité avec le plus grand respect.
          </p>
          <p className="text-white text-lg leading-relaxed font-medium italic opacity-90">
            Notre secret ? Une équipe de chefs passionnés qui marient tradition et innovation. Nos pâtes à pizza reposent pendant 48 heures pour une légèreté incomparable. Chez FastDélice, chaque bouchée raconte une histoire d'excellence.
          </p>
        </div>
        <div className="mt-12 text-center text-white/70 italic text-sm">"La qualité n'est pas un acte, c'est une habitude."</div>
      </div>
    </div>
  </PageLayout>
);

// --- CONTACT ---
const Contact = () => (
  <PageLayout title="Contactez-Nous">
    <div className="max-w-4xl mx-auto grid grid-cols-1 md:grid-cols-2 gap-10">
      <div className="bg-white/10 backdrop-blur-xl border border-white/20 p-10 rounded-[3rem] shadow-2xl">
        <h3 className="text-2xl font-black text-orange-600 italic mb-6 uppercase">Coordonnées</h3>
        <div className="space-y-6 text-white font-medium italic">
          <div><p className="text-orange-500 font-black text-[10px] uppercase mb-1 tracking-widest">Adresse</p><p>123 Boulevard Gourmand, Casablanca</p></div>
          <div><p className="text-orange-500 font-black text-[10px] uppercase mb-1 tracking-widest">Téléphone</p><p>+212 522 12 34 56</p></div>
          <div><p className="text-orange-500 font-black text-[10px] uppercase mb-1 tracking-widest">Email</p><p>contact@fastdelice.ma</p></div>
        </div>
      </div>
      <form className="bg-black/40 backdrop-blur-xl border border-white/10 p-10 rounded-[3rem] space-y-4">
        <input type="text" placeholder="NOM" className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white text-xs font-bold uppercase outline-none focus:border-orange-600 transition" />
        <textarea placeholder="MESSAGE" rows="4" className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white text-xs font-bold uppercase outline-none focus:border-orange-600 transition"></textarea>
        <button className="w-full bg-orange-600 text-white py-5 rounded-2xl font-black uppercase tracking-widest hover:bg-white hover:text-black transition shadow-lg">Envoyer</button>
      </form>
    </div>
  </PageLayout>
);

// --- HOME ---
const Home = () => {
  const testimonials = [
    { n: "SARAH B.", t: "La meilleure pizza que j'ai mangée à Fès!", s: "★★★★★" },
    { n: "AHMED L.", t: "Livraison rapide et plats chauds. Top!", s: "★★★★★" },
    { n: "YOUSSEF M.", t: "Qualité exceptionnelle pour le prix.", s: "★★★★" }
  ];
  return (
    <div className="flex flex-col min-h-screen bg-white">
      <div className="relative h-[90vh] flex items-center justify-center overflow-hidden">
        <div className="absolute inset-0 z-0">
          <img src="https://images.unsplash.com/photo-1513104890138-7c749659a591?q=80&w=2070" className="w-full h-full object-cover" alt="Hero" />
          <div className="absolute inset-0 bg-black/60 backdrop-blur-[2px]"></div>
        </div>
        <div className="relative z-10 text-center px-6">
          <h1 className="text-7xl md:text-9xl font-black text-white mb-6 tracking-tighter italic">Fast<span className="text-orange-600">Délice</span></h1>
          <p className="text-xl text-white mb-12 font-black italic opacity-90">"La passion du goût, l'élégance du service."</p>
          <Link to="/menu" className="bg-orange-600 text-white px-14 py-5 rounded-full font-black uppercase text-sm tracking-widest hover:bg-white hover:text-orange-600 transition shadow-2xl inline-block">Commander Maintenant</Link>
        </div>
      </div>
      <div className="bg-white py-24 px-6">
        <div className="max-w-7xl mx-auto grid grid-cols-1 md:grid-cols-3 gap-8">
          {testimonials.map((v, i) => (
            <div key={i} className="bg-gray-50 p-10 rounded-[3rem] border border-gray-100 text-center">
              <div className="text-orange-500 mb-6 text-sm">{v.s}</div>
              <p className="text-gray-700 italic font-bold mb-8 text-lg leading-relaxed">"{v.t}"</p>
              <span className="text-[10px] font-black text-orange-600 uppercase tracking-widest">— {v.n}</span>
            </div>
          ))}
        </div>
      </div>
      <footer className="bg-gray-50 py-8 border-t border-gray-100 text-center">
        <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.3em]">© 2026 FAST DÉLICE. TOUS DROITS RÉSERVÉS.</p>
      </footer>
    </div>
  );
};

// --- MENU ---
// --- MENU ---
const Menu = ({ categories, addToCart, isFlying }) => {
  const [selectedItem, setSelectedItem] = useState(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [activeCategory, setActiveCategory] = useState("Tout");

  const allDishes = categories.flatMap(c => (c.dishes || []).map(dish => ({ ...dish, categoryName: c.name })));
  const filteredDishes = allDishes.filter(item => 
    (activeCategory === "Tout" || item.categoryName === activeCategory) && 
    item.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <PageLayout title="Menu">

      {/* 🍕 PIZZA ANIMATION - TI-TIR NICHEN L-CHBKA LI F L-NAVBAR */}
      <AnimatePresence>
        {isFlying && (
          <motion.div
            initial={{ 
              top: "50%", 
              left: "50%", 
              scale: 1, 
              opacity: 1 
            }}
            animate={{ 
              top: "30px",      // Kat-tle3 l-blast l-navbar
              left: "90%",      // Kat-mchi l-jiht l-panier f l-imin
              scale: 0.1, 
              opacity: 0,
              rotate: 360 
            }}
            transition={{ 
              duration: 0.8, 
              ease: [0.4, 0, 0.2, 1] // Animation smooth
            }}
            className="fixed z-[9999] pointer-events-none text-6xl"
            style={{ 
              transform: 'translate(-50%, -50%)',
              position: 'fixed'
            }}
          >
            🍕
          </motion.div>
        )}
      </AnimatePresence>

      {/* RECHERCHE */}
      <div className="max-w-md mx-auto mb-8">
        <input 
          type="text" 
          placeholder="RECHERCHER..." 
          className="w-full bg-white/5 border border-white/10 rounded-full py-5 px-10 text-white text-center font-black uppercase text-xs outline-none focus:border-orange-600 transition" 
          onChange={(e) => setSearchTerm(e.target.value)} 
        />
      </div>

      {/* CATEGORIES */}
      <div className="flex flex-wrap justify-center gap-3 mb-16">
        <button 
          onClick={() => setActiveCategory("Tout")} 
          className={`px-8 py-3 rounded-full font-black uppercase text-[13px] transition ${activeCategory === "Tout" ? "bg-orange-600 text-white shadow-lg" : "text-white/50 border border-white/10 hover:border-white/30"}`}
        >
          Tout
        </button>
        {categories.map(cat => (
          <button 
            key={cat.id} 
            onClick={() => setActiveCategory(cat.name)} 
            className={`px-8 py-3 rounded-full font-black uppercase text-[13px] transition ${activeCategory === cat.name ? "bg-orange-600 text-white shadow-lg" : "text-white/50 border border-white/10 hover:border-white/30"}`}
          >
            {cat.name}
          </button>
        ))}
      </div>

      {/* DISHES GRID */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
        {filteredDishes.map(item => (
          <div key={item.id} className="bg-black/40 border border-white/10 rounded-[3rem] p-8 text-center group relative overflow-hidden">
            <div className="h-64 overflow-hidden rounded-2xl mb-6">
              <img src={item.image || "https://via.placeholder.com/300"} alt={item.name} className="w-full h-full object-cover group-hover:scale-110 transition duration-500" />
            </div>
            <h3 className="text-2xl font-black text-white italic mb-2 uppercase">{item.name}</h3>
            <p className="text-orange-500 font-black text-2xl mb-6">{item.price} DH</p>
            <button 
              onClick={() => setSelectedItem(item)} 
              className="w-full py-4 bg-white rounded-2xl font-black uppercase text-[10px] hover:bg-orange-600 hover:text-white transition shadow-lg active:scale-95"
            >
              Commander
            </button>
          </div>
        ))}
      </div>

      {/* MODAL CHOIX MODE (SUR PLACE / A EMPORTER) */}
      {selectedItem && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-md">
          <motion.div 
            initial={{ scale: 0.9, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            className="bg-white rounded-[3.5rem] p-12 max-w-sm w-full text-center shadow-2xl"
          >
            <h3 className="text-3xl font-black mb-8 italic uppercase tracking-tighter">Votre Mode?</h3>
            <div className="space-y-4">
              <button 
                onClick={() => { addToCart({...selectedItem, type: 'Sur Place'}); setSelectedItem(null); }} 
                className="w-full py-5 bg-gray-100 rounded-2xl font-black uppercase text-sm hover:bg-orange-600 hover:text-white transition-all shadow-md"
              >
                🍽️ Sur Place
              </button>
              <button 
                onClick={() => { addToCart({...selectedItem, type: 'À Emporter'}); setSelectedItem(null); }} 
                className="w-full py-5 bg-gray-900 text-white rounded-2xl font-black uppercase text-sm hover:bg-orange-600 transition-all shadow-md"
              >
                🛍️ À Emporter
              </button>
            </div>
            <button 
              onClick={() => setSelectedItem(null)} 
              className="mt-8 text-gray-400 font-black text-[11px] uppercase tracking-widest hover:text-red-500 transition"
            >
              Fermer
            </button>
          </motion.div>
        </div>
      )}
    </PageLayout>
  );
};

// --- PANIER ---
const Panier = ({ cart, updateQuantity, removeFromCart, validateOrder, orderType }) => (
  <PageLayout title="Panier">
    <div className="max-w-2xl mx-auto bg-white/10 backdrop-blur-2xl border border-white/20 p-8 md:p-12 rounded-[3.5rem] text-white font-bold italic relative">
      {orderType && (
        <div className="absolute top-0 right-0 bg-orange-600 px-6 py-2 rounded-bl-[2rem] text-xs uppercase tracking-tighter not-italic z-10">
          Mode: {orderType}
        </div>
      )}
      {cart.length === 0 ? (
        <p className="text-center opacity-60 uppercase tracking-widest">Votre panier est vide.</p>
      ) : (
        <div className="space-y-6">
          {cart.map((item, i) => (
            <div key={i} className="flex items-center gap-4 border-b border-white/10 py-6">
              <img src={item.image} alt={item.name} className="w-20 h-20 object-cover rounded-2xl border border-white/10 shadow-lg" />
              <div className="flex-1">
                <p className="uppercase text-lg leading-tight">{item.name} <span className="text-orange-500 text-[10px] block md:inline md:ml-2">({item.type})</span></p>
                <p className="text-orange-500 font-black mt-1">{item.price} DH</p>
              </div>
              <div className="flex items-center gap-3 bg-white/5 rounded-2xl p-2 border border-white/10">
                <button onClick={() => updateQuantity(item.id, -1)} className="w-8 h-8 flex items-center justify-center hover:bg-orange-600 rounded-xl transition"> - </button>
                <span className="text-white font-black text-lg w-4 text-center">{item.quantity || 1}</span>
                <button onClick={() => updateQuantity(item.id, 1)} className="w-8 h-8 flex items-center justify-center hover:bg-orange-600 rounded-xl transition"> + </button>
              </div>
              <button onClick={() => removeFromCart(item.id)} className="ml-2 text-white/20 hover:text-red-500 transition text-xl">🗑️</button>
            </div>
          ))}
          <div className="text-3xl font-black pt-8 flex justify-between uppercase italic border-t-2 border-orange-600/30">
            <span>Total:</span>
            <span className="text-orange-600">{cart.reduce((a, b) => a + (parseFloat(b.price) * (b.quantity || 1)), 0)} DH</span>
          </div>
          <button onClick={validateOrder} className="w-full bg-orange-600 text-white py-5 rounded-2xl font-black uppercase tracking-widest hover:bg-white hover:text-black transition shadow-xl mt-6">Valider la commande</button>
        </div>
      )}
    </div>
  </PageLayout>
);

// --- MAIN APP ---
export default function App() {
  const [categories, setCategories] = useState([]);
  const [cart, setCart] = useState([]);
  const [orderType, setOrderType] = useState(""); 
  const [isFlying, setIsFlying] = useState(false);

  const triggerFly = () => {
    setIsFlying(true);
    setTimeout(() => setIsFlying(false), 900);
  };

  const addToCart = (dish) => {
    triggerFly();
    setOrderType(dish.type);
    setCart((prev) => {
      const existing = prev.find(item => item.id === dish.id);
      if (existing) {
        return prev.map(item => item.id === dish.id ? { ...item, quantity: (item.quantity || 1) + 1 } : item);
      }
      return [...prev, { ...dish, quantity: 1, type: dish.type }];
    });
  };

  const validateOrder = async () => {
    if (cart.length === 0) return;
    const total = cart.reduce((acc, item) => acc + (parseFloat(item.price) * (item.quantity || 1)), 0);
    Swal.fire({
      title: 'Succès !',
      text: `Votre commande (${orderType}) de ${total} DH a été validée.`,
      icon: 'success',
      background: '#1a1a1a', color: '#fff', confirmButtonColor: '#ea580c'
    }).then(() => {
      setCart([]);
      window.location.href = "/";
    });
  };

  const updateQuantity = (id, amount) => {
    setCart(prev => prev.map(item => item.id === id ? { ...item, quantity: Math.max(1, (item.quantity || 1) + amount) } : item));
  };

  const removeFromCart = (id) => setCart(prev => prev.filter(item => item.id !== id));

  useEffect(() => {
    axios.get('http://127.0.0.1:8000/api/categories/')
      .then(res => setCategories(res.data))
      .catch(e => console.log(e));
  }, []);

  return (
    <Router>
      <div className="min-h-screen bg-black">
        <Navbar cartCount={cart.length} isFlying={isFlying} />
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/menu" element={<Menu categories={categories} addToCart={addToCart} isFlying={isFlying} />} />
          <Route path="/about" element={<About />} />
          <Route path="/contact" element={<Contact />} />
          <Route path="/login" element={<Login />} />
          <Route path="/register" element={<Register />} />
          <Route path="/panier" element={<Panier cart={cart} updateQuantity={updateQuantity} removeFromCart={removeFromCart} validateOrder={validateOrder} orderType={orderType} />} />
        </Routes>
      </div>
    </Router>
  );
}
